  };

  static Widget icon(String name, {double size = 20, Color? color}) {
    final svg = _svgPaths[name];
    if (svg == null) {
      return SizedBox(width: size, height: size);
    }
    // Replace 'currentColor' with actual color value
    final colored = color != null
        ? svg.replaceAll('currentColor', '#${color.value.toRadixString(16).padLeft(8, '0').substring(2)}')
        : svg;
    return SvgPicture.string(colored, width: size, height: size);
  }
}

/// Convenience widget wrapping AppIcons.icon
class RbIcon extends StatelessWidget {
  const RbIcon(this.name, {super.key, this.size = 20, this.color});

  final String name;
  final double size;
  final Color? color;

  @override
  Widget build(BuildContext context) {
    final cs = Theme.of(context).extension<AppColorScheme>()!;
    return AppIcons.icon(name, size: size, color: color ?? cs.ink);
  }
}
